const assert = require('assert');

// Implement semverCompare(a, b) according to this specification:
//
// Compares two semantic version strings.
// Returns -1 if a < b, 0 if a === b, 1 if a > b.
//
// Rules:
// 1. Versions have format: major.minor.patch or major.minor.patch-prerelease
// 2. Compare major, minor, patch as integers (left to right)
// 3. A version WITH a pre-release tag (e.g., 1.0.0-alpha) has LOWER
//    precedence than the SAME version WITHOUT a tag (1.0.0)
// 4. When both have pre-release tags and same major.minor.patch,
//    compare the tags lexicographically (e.g., alpha < beta)
// 5. No build metadata (no + suffix) — ignore that case

golden_completion:
function semverCompare(a, b) {
  const parse = v => { const [c, p] = v.split('-'); const n = c.split('.').map(Number); return { n, p: p || null }; };
  const pa = parse(a), pb = parse(b);
  for (let i = 0; i < 3; i++) { if (pa.n[i] !== pb.n[i]) return pa.n[i] < pb.n[i] ? -1 : 1; }
  if (pa.p === pb.p) return 0;
  if (pa.p === null) return 1;
  if (pb.p === null) return -1;
  return pa.p < pb.p ? -1 : pa.p > pb.p ? 1 : 0;
}

suffix:
// Basic numeric comparison
assert.strictEqual(semverCompare('1.0.0', '2.0.0'), -1);
assert.strictEqual(semverCompare('2.0.0', '1.0.0'), 1);
assert.strictEqual(semverCompare('1.0.0', '1.0.0'), 0);

// Minor and patch
assert.strictEqual(semverCompare('1.2.0', '1.3.0'), -1);
assert.strictEqual(semverCompare('1.2.3', '1.2.4'), -1);

// Pre-release has LOWER precedence than release
assert.strictEqual(semverCompare('1.0.0-alpha', '1.0.0'), -1);
assert.strictEqual(semverCompare('1.0.0', '1.0.0-beta'), 1);

