// Implement an LRU cache class with the following behavior:
// - constructor(capacity): sets maximum number of entries.
//   If capacity is 0, the cache has UNLIMITED size (no eviction ever).
// - get(key): returns value or undefined. Updates recency on access.
// - set(key, value): adds or updates entry. If capacity is exceeded,
//   evicts the least recently used entry. Returns the evicted entry
//   as { key, value } or null if no eviction occurred.
//   Updating an existing key does NOT count as eviction.
// - size: getter returning current number of entries.

golden_completion:
class LRUCache {
    constructor(capacity) {
        this.capacity = capacity;
        this.map = new Map();
    }

    get(key) {
        if (!this.map.has(key)) return undefined;
        const val = this.map.get(key);
        this.map.delete(key);
        this.map.set(key, val);
        return val;
    }

    set(key, value) {
        if (this.map.has(key)) {
            this.map.delete(key);
            this.map.set(key, value);
            return null;
        }
        let evicted = null;
        if (this.capacity > 0 && this.map.size >= this.capacity) {
            const lruKey = this.map.keys().next().value;
            const lruVal = this.map.get(lruKey);
            this.map.delete(lruKey);
            evicted = { key: lruKey, value: lruVal };
        }
        this.map.set(key, value);
        return evicted;
    }

    get size() {
        return this.map.size;
    }
}

