function customSort(items, primaryKey, secondaryKey) {
    if (!Array.isArray(items)) throw new TypeError('items must be an array');
    return [...items].sort((a, b) => {
        let pa = typeof a[primaryKey] === 'string' ? parseFloat(a[primaryKey]) : a[primaryKey];
        let pb = typeof b[primaryKey] === 'string' ? parseFloat(b[primaryKey]) : b[primaryKey];
        if (isNaN(pa)) pa = -Infinity;
        if (isNaN(pb)) pb = -Infinity;
        if (pb !== pa) return pb - pa; // descending
        const sa = String(a[secondaryKey] || '');
        const sb = String(b[secondaryKey] || '');
        return sa.localeCompare(sb); // ascending
    });
}

// Test basic descending primary sort
const data = [
    { score: 10, name: 'Bob' },
    { score: 30, name: 'Alice' },
    { score: 20, name: 'Charlie' }
];
