// Doc precision checks
const doc = `Creates a reactive state object using a Proxy with get and set traps.
The get trap registers the currently active subscriber (if any) as a
dependency for the accessed property, storing subscribers in a per-property Set.
The set trap performs a strict equality check (===) between the old and new
values; if they differ, it updates the value and synchronously notifies
all subscribers registered for that property by calling each subscriber function.
If the values are strictly equal, no notification occurs.`;
assert.ok(doc.includes('get') && doc.includes('set'), 'Must mention get and set traps');
assert.ok(doc.includes('Proxy'), 'Must mention Proxy');
assert.ok(doc.includes('subscriber') || doc.includes('dependency'), 'Must mention subscribers/dependencies');
assert.ok(doc.includes('strict equality') || doc.includes('==='), 'Must mention strict equality check');
assert.ok(doc.includes('synchronously') || doc.includes('notif'), 'Must mention synchronous notification');
assert.ok(doc.includes('Set'), 'Must mention per-property Set');

// Functional: strict equality check prevents notification
