const assert = require('assert');

class BufferedChannel {
  constructor(highWaterMark = 4) {
    this._buffer = [];
    this._highWaterMark = highWaterMark;
    this._drainCallbacks = [];
    this._closed = false;
  }

suffix:
  enqueue(value) {
    if (this._closed) throw new Error('Channel is closed');
    this._buffer.push(value);
    return this._buffer.length < this._highWaterMark;
  }

  dequeue() {
    const val = this._buffer.shift();
    if (this._buffer.length < this._highWaterMark && this._drainCallbacks.length > 0) {
      const cbs = this._drainCallbacks.splice(0);
      cbs.forEach(cb => cb());
    }
    return val;
  }

  drain() {
    if (this._buffer.length < this._highWaterMark) return Promise.resolve();
    return new Promise(resolve => this._drainCallbacks.push(resolve));
  }

  close() { this._closed = true; }

  get desiredSize() {
    return this._highWaterMark - this._buffer.length;
  }
}

const ch = new BufferedChannel(2);
assert.strictEqual(ch.enqueue('a'), true);  // below hwm
assert.strictEqual(ch.enqueue('b'), false); // at hwm — backpressure
